import unittest

from units import convert


class TestUnits(unittest.TestCase):
    def test_km_to_m(self):
        self.assertAlmostEqual(convert(1.5, "km", "m"), 1500)

    def test_boiling(self):
        self.assertAlmostEqual(convert(100, "C", "F"), 212)

